-- 046_web_makleri.sql
--
-- Weby maklérov: osobné weby maklérov a manažéra pobočky, spravované z CRM
-- (/weby), verejne dostupné na /web/[slug].
--
--   web_sites       — jeden riadok = jeden web. `draft` edituje admin (autosave),
--                     `published` je verejná verzia (kópia draftu po „Publikovať").
--   web_nastavenia  — spoločné texty pobočky (jeden riadok id='default').
--   web_dopyty      — dopyty z formulára „Koľko stojí vaša nehnuteľnosť".
--   storage bucket  — web-fotky (verejný) pre nahrané fotky.
--
-- Prístup: verejné stránky aj API čítajú/zapisujú cez service_role (server),
-- anon má SELECT na web_sites/web_nastavenia (konzistentné s ostatnými tabuľkami),
-- dopyty (osobné údaje) sú len service_role.

BEGIN;

CREATE TABLE IF NOT EXISTS web_nastavenia (
  id          text PRIMARY KEY,
  data        jsonb NOT NULL DEFAULT '{}'::jsonb,
  updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS web_sites (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug          text NOT NULL UNIQUE,
  typ           text NOT NULL DEFAULT 'makler' CHECK (typ IN ('makler', 'manazer')),
  user_id       text REFERENCES users(id) ON DELETE SET NULL,
  poradie       integer NOT NULL DEFAULT 0,
  draft         jsonb NOT NULL DEFAULT '{}'::jsonb,
  published     jsonb,
  published_at  timestamptz,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_web_sites_user ON web_sites(user_id);
CREATE INDEX IF NOT EXISTS idx_web_sites_poradie ON web_sites(poradie);

CREATE OR REPLACE FUNCTION web_sites_set_updated_at()
RETURNS trigger AS $$
BEGIN NEW.updated_at = now(); RETURN NEW; END;
$$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS web_sites_updated_at ON web_sites;
CREATE TRIGGER web_sites_updated_at
  BEFORE UPDATE ON web_sites
  FOR EACH ROW EXECUTE FUNCTION web_sites_set_updated_at();

CREATE TABLE IF NOT EXISTS web_dopyty (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  site_id     uuid REFERENCES web_sites(id) ON DELETE SET NULL,
  site_slug   text NOT NULL,
  data        jsonb NOT NULL,
  ip          text,
  vybavene    boolean NOT NULL DEFAULT false,
  created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_web_dopyty_site ON web_dopyty(site_id);
CREATE INDEX IF NOT EXISTS idx_web_dopyty_created ON web_dopyty(created_at DESC);

-- RLS
ALTER TABLE web_nastavenia ENABLE ROW LEVEL SECURITY;
ALTER TABLE web_sites      ENABLE ROW LEVEL SECURITY;
ALTER TABLE web_dopyty     ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS anon_read_web_nastavenia ON web_nastavenia;
CREATE POLICY anon_read_web_nastavenia ON web_nastavenia FOR SELECT TO anon USING (true);
DROP POLICY IF EXISTS service_role_all_web_nastavenia ON web_nastavenia;
CREATE POLICY service_role_all_web_nastavenia ON web_nastavenia TO service_role USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS anon_read_web_sites ON web_sites;
CREATE POLICY anon_read_web_sites ON web_sites FOR SELECT TO anon USING (true);
DROP POLICY IF EXISTS service_role_all_web_sites ON web_sites;
CREATE POLICY service_role_all_web_sites ON web_sites TO service_role USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS service_role_all_web_dopyty ON web_dopyty;
CREATE POLICY service_role_all_web_dopyty ON web_dopyty TO service_role USING (true) WITH CHECK (true);

-- Storage bucket pre fotky webov (verejné čítanie, zápis len service_role)
INSERT INTO storage.buckets (id, name, public)
VALUES ('web-fotky', 'web-fotky', true)
ON CONFLICT (id) DO NOTHING;

